//! Lock file (`Spark.lock`) management.
//!
//! The lock file records exact commit hashes for git dependencies so that
//! builds are reproducible. Path dependencies are not locked — they always
//! resolve to the local filesystem.
//!
//! ## Format
//!
//! ```toml
//! # This file is auto-generated by the Spark compiler. Do not edit.
//!
//! [[package]]
//! name = "json"
//! source = "git"
//! url = "https://github.com/spark-pkg/json"
//! commit = "abc123def456..."
//! ```

use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::manifest::{Dependency, Manifest};

/// A parsed `Spark.lock` file.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct LockFile {
    /// Locked packages (git dependencies only).
    #[serde(default, rename = "package")]
    pub packages: Vec<LockedPackage>,
}

/// A single locked package entry.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct LockedPackage {
    /// Dependency name.
    pub name: String,
    /// Source type (`"git"` or `"registry"`).
    pub source: String,
    /// Git repository URL or download URL.
    pub url: String,
    /// Exact commit hash (empty for registry deps).
    pub commit: String,
    /// Resolved semver version (for registry deps).
    #[serde(skip_serializing_if = "Option::is_none")]
    pub version: Option<String>,
}

/// Loads a `Spark.lock` file from a project root.
///
/// Returns `None` if no lock file exists. Returns `Some(Err(..))` if the
/// file exists but is malformed.
#[must_use]
pub fn load_lock_file(root: &Path) -> Option<Result<LockFile, String>> {
    let lock_path = root.join("Spark.lock");
    if !lock_path.exists() {
        return None;
    }
    let contents = match std::fs::read_to_string(&lock_path) {
        Ok(s) => s,
        Err(e) => return Some(Err(format!("could not read Spark.lock: {e}"))),
    };
    Some(toml::from_str(&contents).map_err(|e| format!("failed to parse Spark.lock: {e}")))
}

/// Writes a `Spark.lock` file to the project root.
///
/// Only writes if there are locked packages (git dependencies). If there
/// are no git dependencies, no lock file is created.
///
/// # Errors
///
/// Returns an error if the file cannot be written.
pub fn write_lock_file(root: &Path, lock: &LockFile) -> Result<(), String> {
    if lock.packages.is_empty() {
        return Ok(());
    }

    let contents = toml::to_string_pretty(lock)
        .map_err(|e| format!("failed to serialize Spark.lock: {e}"))?;

    let lock_path = root.join("Spark.lock");
    let full_contents = format!(
        "# This file is auto-generated by the Spark compiler. Do not edit.\n\n{contents}"
    );
    std::fs::write(&lock_path, full_contents)
        .map_err(|e| format!("could not write Spark.lock: {e}"))
}

/// Checks whether the lock file is fresh relative to the manifest.
///
/// The lock is considered stale if:
/// - A git dependency in the manifest is missing from the lock
/// - A registry dependency in the manifest is missing from the lock
/// - A locked package is no longer in the manifest
/// - A locked package's URL has changed
/// - A registry dependency's version constraint has changed
///
/// Path dependencies are ignored (they are never locked).
#[must_use]
pub fn is_lock_fresh(manifest: &Manifest, lock: &LockFile) -> bool {
    // Collect lockable deps from manifest (git + registry).
    let mut lockable_count = 0;

    for (name, dep) in &manifest.dependencies {
        match dep {
            Dependency::Git { git, .. } => {
                lockable_count += 1;
                let found = lock
                    .packages
                    .iter()
                    .any(|p| p.name == *name && p.source == "git" && p.url == *git);
                if !found {
                    return false;
                }
            }
            Dependency::Registry(_) => {
                lockable_count += 1;
                let found = lock
                    .packages
                    .iter()
                    .any(|p| p.name == *name && p.source == "registry");
                if !found {
                    return false;
                }
            }
            Dependency::Path { .. } => {}
        }
    }

    // Check that there are no extra locked packages.
    if lockable_count != lock.packages.len() {
        return false;
    }

    true
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn make_manifest(deps: Vec<(&str, Dependency)>) -> Manifest {
        Manifest {
            project: crate::manifest::ProjectSection {
                name: "test".to_string(),
                version: "0.1.0".to_string(),
                entry: "main.spark".to_string(),
                repository: None,
            },
            dependencies: deps
                .into_iter()
                .map(|(k, v)| (k.to_string(), v))
                .collect::<HashMap<_, _>>(),
            build: crate::manifest::BuildSection::default(),
        }
    }

    #[test]
    fn round_trip() {
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "git".to_string(),
                url: "https://github.com/spark-pkg/json".to_string(),
                commit: "abc123def456".to_string(),
                version: None,
            }],
        };

        let serialized = toml::to_string_pretty(&lock).unwrap();
        let deserialized: LockFile = toml::from_str(&serialized).unwrap();
        assert_eq!(lock, deserialized);
    }

    #[test]
    fn fresh_with_matching_deps() {
        let manifest = make_manifest(vec![(
            "json",
            Dependency::Git {
                git: "https://github.com/spark-pkg/json".to_string(),
                tag: Some("v1.0".to_string()),
                branch: None,
                rev: None,
            },
        )]);
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "git".to_string(),
                url: "https://github.com/spark-pkg/json".to_string(),
                commit: "abc123".to_string(),
                version: None,
            }],
        };
        assert!(is_lock_fresh(&manifest, &lock));
    }

    #[test]
    fn stale_on_new_dep() {
        let manifest = make_manifest(vec![
            (
                "json",
                Dependency::Git {
                    git: "https://github.com/spark-pkg/json".to_string(),
                    tag: None,
                    branch: None,
                    rev: None,
                },
            ),
            (
                "http",
                Dependency::Git {
                    git: "https://github.com/spark-pkg/http".to_string(),
                    tag: None,
                    branch: None,
                    rev: None,
                },
            ),
        ]);
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "git".to_string(),
                url: "https://github.com/spark-pkg/json".to_string(),
                commit: "abc123".to_string(),
                version: None,
            }],
        };
        assert!(!is_lock_fresh(&manifest, &lock));
    }

    #[test]
    fn stale_on_removed_dep() {
        let manifest = make_manifest(vec![]);
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "git".to_string(),
                url: "https://github.com/spark-pkg/json".to_string(),
                commit: "abc123".to_string(),
                version: None,
            }],
        };
        assert!(!is_lock_fresh(&manifest, &lock));
    }

    #[test]
    fn stale_on_url_change() {
        let manifest = make_manifest(vec![(
            "json",
            Dependency::Git {
                git: "https://github.com/other/json".to_string(),
                tag: None,
                branch: None,
                rev: None,
            },
        )]);
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "git".to_string(),
                url: "https://github.com/spark-pkg/json".to_string(),
                commit: "abc123".to_string(),
                version: None,
            }],
        };
        assert!(!is_lock_fresh(&manifest, &lock));
    }

    #[test]
    fn path_deps_excluded() {
        let manifest = make_manifest(vec![
            (
                "local",
                Dependency::Path {
                    path: "../local".to_string(),
                },
            ),
        ]);
        let lock = LockFile {
            packages: vec![],
        };
        assert!(is_lock_fresh(&manifest, &lock));
    }

    #[test]
    fn load_nonexistent_lock() {
        let result = load_lock_file(Path::new("/nonexistent/path"));
        assert!(result.is_none());
    }

    #[test]
    fn write_empty_lock_is_noop() {
        let tmp = tempfile::tempdir().unwrap();
        let lock = LockFile {
            packages: vec![],
        };
        write_lock_file(tmp.path(), &lock).unwrap();
        assert!(!tmp.path().join("Spark.lock").exists());
    }

    #[test]
    fn write_and_load_lock() {
        let tmp = tempfile::tempdir().unwrap();
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "git".to_string(),
                url: "https://github.com/spark-pkg/json".to_string(),
                commit: "abc123def456".to_string(),
                version: None,
            }],
        };
        write_lock_file(tmp.path(), &lock).unwrap();

        let loaded = load_lock_file(tmp.path()).unwrap().unwrap();
        assert_eq!(lock, loaded);
    }

    #[test]
    fn registry_lock_round_trip() {
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "registry".to_string(),
                url: "http://example.com/json-1.0.0.tar.gz".to_string(),
                commit: String::new(),
                version: Some("1.0.0".to_string()),
            }],
        };

        let tmp = tempfile::tempdir().unwrap();
        write_lock_file(tmp.path(), &lock).unwrap();
        let loaded = load_lock_file(tmp.path()).unwrap().unwrap();
        assert_eq!(lock, loaded);
    }

    #[test]
    fn fresh_with_registry_deps() {
        let manifest = make_manifest(vec![(
            "json",
            Dependency::Registry("1.0.0".to_string()),
        )]);
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "registry".to_string(),
                url: "http://example.com/json-1.0.0.tar.gz".to_string(),
                commit: String::new(),
                version: Some("1.0.0".to_string()),
            }],
        };
        assert!(is_lock_fresh(&manifest, &lock));
    }

    #[test]
    fn stale_on_new_registry_dep() {
        let manifest = make_manifest(vec![
            ("json", Dependency::Registry("1.0.0".to_string())),
            ("http", Dependency::Registry("2.0.0".to_string())),
        ]);
        let lock = LockFile {
            packages: vec![LockedPackage {
                name: "json".to_string(),
                source: "registry".to_string(),
                url: "http://example.com/json-1.0.0.tar.gz".to_string(),
                commit: String::new(),
                version: Some("1.0.0".to_string()),
            }],
        };
        assert!(!is_lock_fresh(&manifest, &lock));
    }

    #[test]
    fn fresh_with_mixed_git_and_registry() {
        let manifest = make_manifest(vec![
            (
                "json",
                Dependency::Git {
                    git: "https://github.com/spark-pkg/json".to_string(),
                    tag: None,
                    branch: None,
                    rev: None,
                },
            ),
            ("http", Dependency::Registry("1.0.0".to_string())),
        ]);
        let lock = LockFile {
            packages: vec![
                LockedPackage {
                    name: "json".to_string(),
                    source: "git".to_string(),
                    url: "https://github.com/spark-pkg/json".to_string(),
                    commit: "abc123".to_string(),
                    version: None,
                },
                LockedPackage {
                    name: "http".to_string(),
                    source: "registry".to_string(),
                    url: "http://example.com/http-1.0.0.tar.gz".to_string(),
                    commit: String::new(),
                    version: Some("1.0.0".to_string()),
                },
            ],
        };
        assert!(is_lock_fresh(&manifest, &lock));
    }
}
